import{z as L,x as c,o as l,c as i,q as t,j as r,D as E,d as e,s as d,S as s,b as o}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"空值与三值逻辑","description":"","frontmatter":{"title":"空值与三值逻辑","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sql-null.md","filePath":"cs/sql-null.md","lastUpdated":1791063341000}'),N={name:"cs/sql-null.md"};function A(B,a,p,U,u,C){const n=c("Mermaid");return l(),i("div",null,[a[2]||(a[2]=t('<h1 id="空值与三值逻辑" tabindex="-1">空值与三值逻辑 <a class="header-anchor" href="#空值与三值逻辑" aria-label="Permalink to &quot;空值与三值逻辑&quot;">​</a></h1><div class="epigraph"><p>NULL 不是域里的值；谓词遇上它得到 unknown，WHERE 只留真，于是同一表达式不再总服从集合代数的直觉。</p><footer>—— 据 Date 对缺失信息的批评；SQL 标准三值逻辑；Codd 后来的标记方案对照</footer></div><p><a href="/cs/sql-declarative">上一课</a>把查询写成声明：含义应对准代数。本课不重写 SELECT。缺口是 SQL 允许缺失：外键置空、未填列。若把 NULL 当普通值，相等与连接会把「不知道」当成匹配或当成不等，两种都会错。三值逻辑是工程合同，不是关系模型 1970 的一部分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/relational-model">关系模型</a> 的域里每个属性有值。SQL 增加 NULL。比较结果是 true / false / unknown；<code>WHERE</code> 与 <code>HAVING</code> 保留 true。<code>NOT unknown</code> 仍是 unknown。连接在 NULL 上不匹配。缺口是<strong>声明语义相对集合代数的缝</strong>，以便后课连接算法不要把 NULL 当哈希键上的普通字节就完事。</p><p><span class="marginnote">Date 主张避免 NULL。主干承认 SQL 有它，并用三值把坑钉死：<code>x = x</code> 在 x 为 NULL 时不是真；<code>UNIQUE</code> 对多 NULL 的行为按标准版本而异。</span></p><p><span class="marginnote">直觉类比：NULL 是「考卷没交」，不是「0 分」。问「他及格了吗」答案不是「否」而是「无从判断」——所以 <code>age \\gt 18</code> 与 <code>NOT (age \\gt 18)</code> 在 age 缺失时都留不下该行，缺value的记录两头都进不去。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>求值：算术与比较遇 NULL 变 unknown（除少数 <code>IS NULL</code>）。聚合默认跳过 NULL，<code>COUNT(*)</code> 例外。外连接用 NULL 填不成配的一侧——这是有意的标记，不是「零」。本课不把全部标准边角写成百科。</p>',9)),(l(),r(s,null,{default:E(()=>[d(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%B0%93%E8%AF%8D%22%5D%20--%3E%20TV%5B%22%E7%9C%9F%20%2F%20%E5%81%87%20%2F%20%E6%9C%AA%E7%9F%A5%22%5D%0A%20%20TV%20--%3E%20W%5B%22WHERE%20%E5%8F%AA%E7%95%99%E7%9C%9F%22%5D%0A%20%20NULL%5B%22NULL%20%E5%8F%82%E4%B8%8E%E6%AF%94%E8%BE%83%22%5D%20--%3E%20UNK%5B%22%E6%9C%AA%E7%9F%A5%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,[e("三值使优化器的某些代数律失效：选择下推遇到 NULL 与外连接时要检查。哈希连接把 NULL 当不相等，嵌套循环同样。完整性：主键不允许 NULL；外键列可空是"),o("a",{href:"/cs/fk-actions"},"参照动作"),e(" 置空的前提。")],-1)),(l(),r(s,null,{default:E(()=>[d(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%20NULL%22%5D%20--%3E%20C%5B%22%E6%AF%94%E8%BE%83%3A%20NULL%20%3D%20NULL%20%E5%BE%97%20unknown%3Cbr%2F%3EWHERE%20%E4%B8%80%E8%A1%8C%E9%83%BD%E4%B8%8D%E7%95%99%22%5D%0A%20%20N%20--%3E%20J%5B%22%E8%BF%9E%E6%8E%A5%3A%20NULL%20%E4%B8%8D%E4%B8%8E%E4%BB%BB%E4%BD%95%E9%94%AE%E5%8C%B9%E9%85%8D%3Cbr%2F%3E%E5%86%85%E8%BF%9E%E6%8E%A5%E4%B8%A2%E8%A1%8C%EF%BC%8C%E5%A4%96%E8%BF%9E%E6%8E%A5%E8%A1%A5%20NULL%22%5D%0A%20%20N%20--%3E%20AG1%5B%22COUNT(*)%3A%20%E6%95%B0%E8%A1%8C%2C%20NULL%20%E4%B9%9F%E7%AE%97%22%5D%0A%20%20N%20--%3E%20AG2%5B%22COUNT(col)%20%2F%20SUM%3A%20%E8%B7%B3%E8%BF%87%20NULL%3Cbr%2F%3E%E5%85%A8%20NULL%20%E6%97%B6%20SUM%20%E4%B8%BA%20NULL%20%E9%9D%9E%200%22%5D%0A%20%20N%20--%3E%20IS%5B%22IS%20NULL%3A%20%E6%98%BE%E5%BC%8F%E5%88%A4%E7%BC%BA%E5%A4%B1%3Cbr%2F%3E%E5%94%AF%E4%B8%80%E6%8B%BF%E5%88%B0%20true%20%E7%9A%84%E5%86%99%E6%B3%95%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">数字实例：10 行表里 3 行 salary 为 NULL——<code>COUNT(*)</code> 得 10，<code>COUNT(salary)</code> 得 7，<code>SUM(salary)</code> 只加 7 个数。对账时把这两个 COUNT 混用，差额恰好是缺失行数。</span></p><p><span class="marginnote">常见误区：初学者容易写 <code>WHERE col = NULL</code>，永远查不到任何行（结果是 unknown 不是 true）。判缺失只有一种写法：<code>WHERE col IS NULL</code>，判非缺失用 <code>IS NOT NULL</code>。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入第四种逻辑或 Codd 的 A/I 标记当主干。物理上连接怎么扫表，下一课连接算法总览。</p><p>后课默认：SQL 结果按三值过滤。同一逻辑连接仍有多种物理算法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NULL 产生 unknown；WHERE 不留未知。</li><li>部分代数律在 SQL 里要加条件。</li><li>连接的物理实现下一课。</li><li>出处：SQL 三值逻辑；Date；对照 Codd。</li></ul>',7))])}const D=L(N,[["render",A]]);export{h as __pageData,D as default};
